const $=s=>document.querySelector(s), money=n=>new Intl.NumberFormat('ru-RU',{style:'currency',currency:'RUB',maximumFractionDigits:2}).format(n/100);
const fresh=()=>({connected:false,joined:false,paid:false,refunded:false,renewed:false,sent:false,rate:20,period:'09',late:false});
let current=location.hash.match(/^#([ABC])$/)?.[1]||document.body.dataset.start||'A', step=0, states={A:fresh(),B:fresh(),C:fresh()},showMeta=true,noticeTimer;
const v=()=>VARIANTS[current],s=()=>states[current],amount=()=>s().paid?99000:0,commission=()=>Math.round(amount()*s().rate/100),adjustment=()=>s().refunded?Math.round(33000*s().rate/100):0;
const net=()=>commission()-adjustment(),esc=str=>String(str).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(t){$('#feedback').textContent=t;clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>$('#feedback').textContent='',5500)}
function button(label,action,primary=false,disabled=false){return `<button type="button" data-action="${action}" class="${primary?'primary':''}" ${disabled?'disabled':''}>${label}</button>`}
function info(t,warn=false){return `<div class="info ${warn?'warn':''}">${t}</div>`}
function head(k,title,text){return `<span class="eyebrow">${k}</span><h1 tabindex="-1">${title}</h1><p class="lead">${text}</p>`}
function demoNote(){return '<p class="readonly">Демонстрационный сценарий. Данные, ставка и действия не относятся к реальным расчётам.</p>'}
function invitation(){return `<label class="field">Ссылка Анны на Proofwall<input readonly value="https://proofwall.example/?ref=ANNA" aria-label="Демонстрационная партнёрская ссылка"></label><label class="field">Промокод<input readonly value="ANNA" aria-label="Промокод партнёра"></label><p class="note">Промокод имеет приоритет над cookie. Cookie: 30 дней. Эти правила предлагаются для PRD.</p>`}
function stat(label,value){return `<div class="stat"><small>${label}</small><strong>${value}</strong></div>`}
function monthly(){const oct=s().period==='10';const gross=oct?(s().renewed?Math.round(99000*s().rate/100):0):commission();const adj=oct?0:adjustment();return {oct,gross,adj,total:gross-adj,month:oct?'Октябрь':'Сентябрь',date:oct?'5 ноября':'5 октября'}}
function renderScene(){const type=v().types[step];
 if(type==='setup')return `<div class="hero"><div>${head('Программа Proofwall','Рекомендации, за которые хочется платить.','Настройте условия один раз. Партнёр увидит каждую засчитанную оплату и дату выплаты.')}<label class="field">Комиссия с оплаты, %<input id="rate" type="number" min="1" max="50" step="1" value="${s().rate}" ${s().paid?'disabled':''}><small>Демо-условие, не утверждённая ставка. После оплаты ставка в этом примере фиксируется.</small></label>${button(s().connected?'Настройка отмечена':'Показать подключение N1','connect',true)}${demoNote()}</div><div class="poster"><span class="tag">Первая интеграция · N1</span><h2 style="margin-top:20px">Proofwall</h2><p>Сбор отзывов и «Стена любви»</p><div class="flow-item"><span>Оплата клиента</span><strong>ЮKassa</strong></div><div class="flow-item"><span>Учёт партнёров</span><strong>N3a</strong></div><div class="flow-item"><span>Вы перечисляете</span><strong>5-го числа</strong></div><p class="note">За предыдущий календарный месяц. Переводы выполняются вручную.</p></div></div>`;
 if(type==='public')return `<div class="hero"><div>${head('Открытая программа · Proofwall','Рекомендуйте то, чем пользуетесь сами.',`${s().rate}% с каждой засчитанной оплаты привлечённого клиента, включая его продления.`)}<div class="pill-list"><span>Выплата 5-го числа</span><span>Ссылка + промокод</span><span>Прозрачные начисления</span></div>${button('Посмотреть вступление','next',true)}<p class="note">За прошлый месяц. Условия показаны до регистрации.</p></div><div class="poster"><span class="eyebrow">Пример вознаграждения</span><div class="big">${money(99000*s().rate/100)}</div><p>с оплаты Proofwall в 990 ₽ при ставке ${s().rate}%</p><hr class="divider"><p>Регистрация без оплаты: 0 ₽.<br>Возврат: отдельная корректировка.<br>Перевод: вручную владельцем.</p>${button('Программа работает на N3a ↗','badge')}</div></div>${demoNote()}`;
 if(type==='join')return `${head('Участие в программе','Условия известны. Можно начинать.','Создайте партнёрский профиль и получите ссылку на Proofwall.')}<div class="form-grid"><label class="field">Имя в примере<input value="Анна" readonly></label><label class="field">Программа<input value="Proofwall · N1" readonly></label></div>${info(`${s().rate}% от засчитанных оплат. Выплаты — 5-го числа за прошлый месяц. Возвраты уменьшают начисления.`)}<label class="checkline"><input id="consent" type="checkbox" ${s().joined?'checked':''}>Я ознакомилась с демонстрационными условиями программы.</label><div id="consent-error" class="consent-error" role="alert"></div>${button(s().joined?'Показать мою ссылку':'Получить ссылку в демо','join',true)}${s().joined?invitation():''}${demoNote()}`;
 if(type==='invite')return `${head('Рекомендация · Анна','Одна ссылка. Понятные условия.',`Анна приглашает клиента в Proofwall и получает ${s().rate}% от его засчитанных оплат.`)}${invitation()}<div class="actions">${button('Скопировать текст рекомендации','copy-invite',true)}${button(current==='C'?'Перейти к проверке продажи':'Пройти путь клиента','next')}</div>${info('Перечисление — 5-го числа за прошлый месяц. Никакие сообщения и приглашения не отправляются автоматически.')}${demoNote()}`;
 if(type==='payment')return `${head('Клиент Proofwall · Михаил','Рекомендация дошла до оплаты.','Регистрация связана с промокодом ANNA. Следующий шаг — оплата продукта N1 через ЮKassa.')}<div class="stats">${stat('Регистрация','1')}${stat('Оплата',s().paid?'990 ₽':'—')}${stat('Комиссия',money(commission()))}</div><div class="flow-item"><div><strong>Proofwall · 30 дней</strong><p style="margin:4px 0 0;font-size:12px">15 сентября · демонстрационный платёж</p></div><strong>990 ₽</strong></div><div class="actions">${button(s().paid?'Оплата показана':'Показать подтверждённую оплату','pay',true,s().paid)}${button('Показать повтор уведомления','duplicate',false,!s().paid)}</div>${info(s().paid?'В примере оплата подтверждена. Партнёру начислено '+money(commission())+'. Повтор уведомления не меняет сумму.':'Пока клиент только зарегистрировался: комиссия 0 ₽. Возвращение со страницы оплаты само по себе не подтверждает платёж.')}${demoNote()}`;
 if(type==='ledger')return `${head('Кабинет партнёра · Анна',s().paid?'Первая комиссия — в кабинете.':'Здесь появится первая комиссия.','Каждая оплата и корректировка видны отдельно. Сумма начисления ещё не означает, что деньги перечислены.')}<div class="stats">${stat('Начислено за сентябрь',money(commission()))}${stat('Корректировки',money(-adjustment()))}${stat('К выплате 5 октября',money(s().sent?0:net()))}</div><div class="table-wrap"><table><thead><tr><th>Дата</th><th>Событие</th><th>Комиссия</th></tr></thead><tbody>${s().paid?`<tr><td>15.09</td><td>Оплата Proofwall · 990 ₽</td><td>${money(commission())}</td></tr>`:'<tr><td colspan="3">Подтверждённых оплат пока нет</td></tr>'}${s().refunded?`<tr><td>20.09</td><td>Частичный возврат · 330 ₽</td><td>−${money(adjustment())}</td></tr>`:''}${s().renewed?`<tr><td>15.10</td><td>Ручное продление · 990 ₽</td><td>${money(commission())}</td></tr>`:''}</tbody></table></div><div class="actions">${button('Показать оплату','pay',true,s().paid)}${button('Возврат 330 ₽ в сентябре','refund',false,!s().paid||s().refunded||s().sent)}${button('Продление 15 октября','renew',false,!s().paid||s().renewed)}${button('Поделиться результатом','share',false,!s().paid)}</div><p class="note">Продление относится к октябрю и выплате 5 ноября. N1 сейчас использует ручные продления, не автоматические списания.</p>${info('MRR: нет подтверждённых данных о подписке. В прототипе показываем фактические оплаты, не выдаём их за MRR.')}${demoNote()}`;
 if(type==='payout'){const m=monthly();return `${head('Расчётный календарь','5-е число. Всё готово к переводу.','Сформируйте таблицу за прошлый месяц, перечислите деньги самостоятельно и затем отметьте выплату.')}<div class="period"><label for="period">Расчётный месяц</label><select id="period"><option value="09" ${!m.oct?'selected':''}>Сентябрь 2026</option><option value="10" ${m.oct?'selected':''}>Октябрь 2026</option></select><span class="tag">Перевод: ${m.date}</span></div><div class="table-wrap"><table><thead><tr><th>Партнёр</th><th>Начислено</th><th>Корректировки</th><th>К переводу</th></tr></thead><tbody><tr><td>Анна · ANNA</td><td>${money(m.gross)}</td><td>−${money(m.adj)}</td><td><strong>${money(m.total)}</strong></td></tr></tbody></table></div><div class="flow-item"><span>Статус реестра · ${m.month}</span><strong class="status">${!m.oct&&s().sent?'Отмечено вручную · 05.10':m.total?'Ожидает ручного перевода':'Нет начислений'}</strong></div><div class="actions">${button('Скачать таблицу CSV','csv',true)}${button('Отметить перевод '+m.date,'mark',false,m.oct||!m.total||s().sent)}</div>${info('CSV — таблица начислений, а не отправка в банк. Демонстрационные суммы до применимых налоговых удержаний: налоговый расчёт здесь не моделируется.')}<p class="note">Поздние возвраты будут отдельными корректировками. Выплаченная история не переписывается.</p>${demoNote()}`}
 if(type==='assisted')return `<div class="hero"><div>${head('Первый запуск · вместе с владельцем','Сначала убедимся, что цифрам можно доверять.','На примере Proofwall пройдём регистрацию, оплату и начисление. Затем пригласим первых партнёров.')}<ul class="summary-list"><li>01 · Условия и дата ручной выплаты</li><li>02 · Путь клиента N1 и подтверждение оплаты</li><li>03 · Сверка комиссии и месячного реестра</li></ul>${button('Начать демонстрационный разбор','next',true)}</div><div class="poster"><span class="tag">Сопровождение человеком</span><h2 style="margin-top:20px">Одна программа.<br>Один понятный расчёт.</h2><p>Первое подключение — Proofwall. Массовые интеграции не нужны для проверки гипотезы.</p><div class="flow-item"><span>Результат встречи</span><strong>Проверенный путь</strong></div><p class="note">В макете встреча не бронируется.</p></div></div>`;
 if(type==='verify')return `${head('Проверка программы','От оплаты N1 до вашей таблицы.','До приглашения партнёров согласуем, что считаем результатом и когда перечисляем деньги.')}<div class="flow-item"><span>Источник продаж</span><strong>Proofwall · N1</strong></div><div class="flow-item"><span>Подтверждение оплаты</span><strong>ЮKassa</strong></div><div class="flow-item"><span>Расчёт вознаграждения</span><strong>N3a · ${s().rate}%</strong></div><div class="flow-item"><span>Выплата</span><strong>5-го за прошлый месяц</strong></div>${info('Повтор одного события не создаёт вторую комиссию. Если данные задержались, показываем ожидание сверки.')}${button(s().connected?'Маршрут отмечен':'Отметить маршрут проверенным в демо','connect',true)}${demoNote()}`;
 if(type==='reconcile')return `${head('Контроль владельца','Оплата, комиссия, реестр — одна цепочка.','Первая продажа должна отразиться в двух кабинетах и в расчёте за месяц.')}<div class="stats">${stat('Оплата N1',s().paid?'990 ₽':'—')}${stat('Комиссия N3a',s().late?'Ожидаем':money(commission()))}${stat('Разница',s().late?'Проверить':'0 ₽')}</div><div class="flow-item"><span>Сверка первого платежа</span><strong class="status">${s().late?'Данные задержаны':s().paid?'Совпадает':'Ожидает оплаты'}</strong></div><div class="actions">${button('Показать продажу и комиссию','pay',true,s().paid&&!s().late)}${button(s().late?'Восстановить сверку':'Показать задержку данных','delay',false,!s().paid)}${button('Подготовить текст кейса','share',false,!s().paid||s().late)}</div>${info(s().late?'Оплата N1 не отменена. До завершения сверки реестр нельзя считать полным.':'Вся партнёрская задолженность по этому сценарию учитывается в N3a; двойное начисление в N1 недопустимо.',s().late)}${demoNote()}`;
 if(type==='growth'){const b=current==='B',c=current==='C';return `${head('Следующий круг',b?'За программой виден продукт.':c?'Подтверждённый результат можно показать.':'Первый результат — повод рекомендовать.',b?'Посетитель публичной страницы может узнать о платформе по badge. Это источник показов, а не обещание новых клиентов.':c?'Владелец делится кейсом с коллегой после первой сверенной комиссии. Следующее подключение начинается с разговора.':'После первой подтверждённой комиссии владелец может рекомендовать платформу коллегам через её собственную партнёрскую программу.')}<div class="poster"><span class="tag">${v().loop}</span><h2 style="margin-top:16px">${b?'Партнёрская программа Proofwall':c?'Proofwall: от оплаты до реестра':'Моя первая партнёрская комиссия'}</h2><p>${s().paid?'В демонстрации начислено '+money(commission())+'.':'Для примера сначала покажите оплату на предыдущих шагах.'}</p><div class="actions">${button(b?'Посмотреть переход по badge':c?'Подготовить текст кейса':'Подготовить рекомендацию',b?'badge':'share',true,!b&&!s().paid)}${button('Посмотреть платную опцию','paywall')}</div></div>${info('На бесплатном тарифе — badge. Снятие брендинга — платная опция для владельца; цена пока не определена. Для пилота подключён только N1.')}${demoNote()}`}
 return '';
}
function render(focus=false){document.title=`N3a · CJM ${current} — ${v().short}`;$('#variant-panel').setAttribute('aria-labelledby','tab-'+current);document.querySelectorAll('[data-variant]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.variant===current)));$('#steps').innerHTML=v().steps.map((name,i)=>`<button data-step="${i}" ${i===step?'aria-current="step"':''}><b>${i+1}</b>${name}</button>`).join('');$('#actor').textContent=v().roles[step];$('#scene').innerHTML=renderScene();$('#count').textContent=`${step+1} / ${v().steps.length}`;$('#prev').disabled=step===0;$('#next').textContent=step===5?'Сравнить варианты':'Следующий шаг →';$('#side-title').textContent=`Вариант ${current}`;$('#side-data').innerHTML=`<dt>Для кого</dt><dd>${v().segment}</dd><dt>Механика роста</dt><dd>${v().loop}</dd><dt>Момент ценности</dt><dd>${v().aha}</dd><dt>Главный риск</dt><dd class="risk">${v().risk}</dd>`;$('#choose-current').textContent=`Обсудить вариант ${current}`;const meta=SCENE_META[v().types[step]];$('#meta').innerHTML=`<div><strong>Задача шага · ${meta[0]}</strong><p>${meta[1]}</p></div><div><strong>Ощущение пользователя</strong><p>${v().emotion[step]}</p></div>`;$('#meta').hidden=!showMeta;if(focus)$('#scene h1')?.focus({preventScroll:true})}
function changeVariant(id){if(!VARIANTS[id])return;current=id;step=0;history.replaceState(null,'','#'+id);render()}
function download(name,text,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Текст скопирован. Отправьте его самостоятельно.')}catch{showDialog('Текст для копирования',`<label class="field">Скопируйте текст вручную<textarea readonly rows="5">${esc(text)}</textarea></label>`)} }
function showDialog(title,body){$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=body;$('#dialog').showModal()}
function compare(){showDialog('Три гипотезы. Одно ядро.',`<p>Все варианты: N1 → ЮKassa → комиссия → ручная выплата 5-го числа. Отличаются вход, основной канал роста и порядок экранов.</p><div class="table-wrap"><table class="compare"><thead><tr><th>Развилка</th>${Object.entries(VARIANTS).map(([id,x])=>`<th>${id} · ${x.short}</th>`).join('')}</tr></thead><tbody>${[['Сегмент','segment'],['Первый крючок','hook'],['Механика роста','loop'],['Момент ценности','aha'],['Монетизация','paywall'],['Риск','risk']].map(([label,key])=>`<tr><td><strong>${label}</strong></td>${Object.values(VARIANTS).map(x=>`<td>${x[key]}</td>`).join('')}</tr>`).join('')}<tr><td>Посмотреть</td>${Object.keys(VARIANTS).map(id=>`<td><button data-preview="${id}">Открыть ${id}</button></td>`).join('')}</tr></tbody></table></div><p class="note">Предварительная рекомендация: A — наиболее близок исходному промпту. Это рекомендация, не зафиксированный выбор.</p><div class="actions">${button('Собрать сочетание','mix')}${button('Подготовить мой выбор','choose',true)}</div>`)}
function choice(mix=false){showDialog(mix?'Собрать сочетание':'Подготовить выбор для обсуждения',`<p>Выбор станет основой PRD только после вашего сообщения и одобрения в чате. Этот HTML ничего не отправляет и не запускает.</p><label class="field">Основной вариант<select id="choice-base">${Object.entries(VARIANTS).map(([id,x])=>`<option value="${id}" ${id===current?'selected':''}>${id} · ${x.short}</option>`).join('')}</select></label>${mix?'<label class="field">Экран входа<select id="choice-entry"><option value="A">A · Настройка владельца</option><option value="B">B · Публичная программа</option><option value="C">C · Разбор с владельцем</option></select></label>':''}<label class="field">Что изменить или взять из другого варианта<textarea id="choice-notes" rows="3" placeholder="Например: путь A, публичная страница B, сверка C"></textarea></label><div class="actions">${button('Скачать мой выбор','export-choice',true)}${button('Скопировать для чата','copy-choice')}</div><p class="note">Одобрение не предполагается. После CJM работа остановлена до вашего решения.</p>`)}
function choiceText(){return `Предлагаю вариант ${$('#choice-base').value} для N3a.${$('#choice-entry')?' Экран входа: '+$('#choice-entry').value+'.':''}\nУточнения: ${$('#choice-notes').value||'нет'}\nОбязательные условия: первая интеграция N1, ЮKassa, ручные выплаты 5-го числа за предыдущий месяц.\nЭто черновик выбора. PRD не создан; решение нужно подтвердить в чате.`}
function next(){if(step===5)return compare();step++;render(true)}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.variant){changeVariant(b.dataset.variant);return}if(b.dataset.step!==undefined){step=Number(b.dataset.step);render(true);return}if(b.dataset.preview){$('#dialog').close();changeVariant(b.dataset.preview);return}const action=b.dataset.action;
 if(action==='next')next();if(action==='prev'){step--;render(true)}if(action==='compare')compare();if(action==='close')$('#dialog').close();if(action==='choose')choice();if(action==='mix')choice(true);
 if(action==='reset'){states[current]=fresh();step=0;render();toast('Демонстрация текущего варианта сброшена.')}
 if(action==='meta'){showMeta=!showMeta;$('#meta').hidden=!showMeta;b.setAttribute('aria-pressed',String(showMeta))}
 if(action==='connect'){const rate=$('#rate');if(rate&&!rate.checkValidity()){rate.reportValidity();return}if(rate)s().rate=Number(rate.value);s().connected=true;render();toast('В демо настройка отмечена. Настоящего подключения нет.')}
 if(action==='join'){if(!$('#consent').checked){$('#consent-error').textContent='Сначала ознакомьтесь с условиями и отметьте согласие.';return}s().joined=true;render();toast('Демо-профиль готов. Ссылка показана ниже.')}
 if(action==='pay'){s().paid=true;s().late=false;render();toast('Демонстрационная оплата N1 засчитана один раз.')}
 if(action==='duplicate'){toast('Повтор получен. Комиссия по той же оплате не начисляется второй раз.')}
 if(action==='refund'&&!s().sent){s().refunded=true;render();toast('Добавлена отдельная корректировка за сентябрь.')}
 if(action==='renew'){s().renewed=true;render();toast('Продление 15 октября: отдельное начисление, выплата 5 ноября.')}
 if(action==='delay'){s().late=!s().late;render()}
 if(action==='csv'){if(s().late){toast('Сначала завершите сверку на шаге «Сверка».');return}const m=monthly();download(`n3a-demo-${m.oct?'october':'september'}-2026.csv`,'\uFEFF'+`ДЕМО — НЕ БАНКОВСКАЯ ОТПРАВКА;Суммы до применимых налоговых удержаний\nПартнёр;Месяц;Начислено RUB;Корректировка RUB;К перечислению RUB;Дата перевода;Статус\nАнна;${m.month} 2026;${m.gross/100};${-m.adj/100};${m.total/100};${m.date};${!m.oct&&s().sent?'Отмечено вручную':'Не перечислено'}\n`,'text/csv;charset=utf-8');toast('Скачана демо-таблица. Статус выплаты не изменён.')}
 if(action==='mark'){if(s().late){toast('Сначала завершите сверку на шаге «Сверка».');return}showDialog('Подтверждение ручной отметки',`<p>Вы отмечаете в демонстрации, что самостоятельно перевели Анне ${money(net())} за сентябрь 5 октября.</p><p>HTML не выполняет банковский перевод.</p>${button('Подтвердить отметку в демо','confirm-mark',true)}`)}
 if(action==='confirm-mark'){s().sent=true;$('#dialog').close();render();toast('Ручная отметка сохранена только в текущей демонстрации.')}
 if(action==='copy-invite')await copy(`Рекомендую Proofwall: https://proofwall.example/?ref=ANNA. Мой код: ANNA. Это демонстрационный текст, адрес example не является рабочим сайтом.`);
 if(action==='share')await copy(`${current==='C'?'Кейс запуска':'Рекомендация платформы'}: N3a помогает учитывать партнёрские комиссии Proofwall и готовить таблицу ручных выплат. В демо первая комиссия — ${money(commission())}. Пример, не реальный результат.`);
 if(action==='badge')showDialog('Переход по badge',`<span class="eyebrow">Платформа N3a</span><h2>Такая программа может быть и у вашего продукта.</h2><p>Так выглядит вход посетителя с публичной страницы программы. Сейчас пилот ограничен N1; подключение другого продукта в этом HTML не выполняется.</p><p class="note">Badge обеспечивает видимость бренда. Конверсии ещё предстоит измерить.</p>`);
 if(action==='paywall')showDialog('Платная опция для владельца',`<h2>Программа под вашим брендом.</h2><p>${v().paywall}</p><p>Цена не определена. Прототип не оформляет подписку и не принимает оплату за N3a.</p><div class="flow-item"><span>Free</span><strong>С badge N3a</strong></div><div class="flow-item"><span>Платный тариф</span><strong>Без badge</strong></div>`);
 if(action==='export-choice')download('n3a-cjm-choice.txt',choiceText());if(action==='copy-choice')await copy(choiceText());
});
document.addEventListener('change',e=>{if(e.target.id==='period'){s().period=e.target.value;render()}if(e.target.id==='rate'&&e.target.checkValidity())s().rate=Number(e.target.value)});
document.querySelectorAll('[data-variant]').forEach((tab,i,all)=>tab.addEventListener('keydown',e=>{let idx=i;if(e.key==='ArrowRight')idx=(i+1)%all.length;else if(e.key==='ArrowLeft')idx=(i+all.length-1)%all.length;else if(e.key==='Home')idx=0;else if(e.key==='End')idx=all.length-1;else return;e.preventDefault();all[idx].focus();changeVariant(all[idx].dataset.variant)}));
render();
